--
-- 表的结构 `player_seasons`
--

DROP TABLE IF EXISTS `player_seasons`;
CREATE TABLE `player_seasons` (
  `player_id` varchar(12) NOT NULL,
  `year_id` smallint(6) NOT NULL,
  `stint` tinyint(4) NOT NULL,
  `team_id` varchar(5) NOT NULL,
  `games` smallint(6) DEFAULT NULL,
  `war` decimal(4,1) DEFAULT NULL,
  `pa` smallint(6) DEFAULT NULL,
  `hr` smallint(6) DEFAULT NULL,
  `rbi` smallint(6) DEFAULT NULL,
  `sb` smallint(6) DEFAULT NULL,
  `avg` decimal(4,3) DEFAULT NULL,
  `ops` decimal(4,3) DEFAULT NULL,
  `ip` decimal(5,1) DEFAULT NULL,
  `p_wins` smallint(6) DEFAULT NULL,
  `p_so` smallint(6) DEFAULT NULL,
  `era` decimal(5,2) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

